from chromadb import GroupBy, MinK, K

# Single grouping key

GroupBy(
    keys=K("category"),
    aggregate=MinK(keys=K.SCORE, k=3)
)

# Multiple grouping keys

GroupBy(
    keys=[K("category"), K("year")],
