def most_common_fruit(fruit_list):

    # Dictionary to get count of each fruit
    freq_dict = {}

    # Count frequency of each fruit
    for fruit in fruit_list:
        if fruit in freq_dict:
            freq_dict[fruit] += 1
        else:
            freq_dict[fruit] = 1

    # Get maximum frequency
    max_freq = 0
    for freq in freq_dict.values():
